CREATE TABLE IF NOT EXISTS vehicles (id TEXT PRIMARY KEY, registration TEXT, make TEXT, model TEXT, year INTEGER, mileage INTEGER, fuel_type TEXT, transmission TEXT, body_type TEXT, colour TEXT, engine_size TEXT, description TEXT, retail_price REAL, offer_price REAL, youtube_url TEXT, main_image_url TEXT, status TEXT DEFAULT 'draft', featured INTEGER DEFAULT 0, extra_json TEXT DEFAULT '{}', title TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
